import{_ as p,a0 as o,w as h,s as d,ao as l,I as n,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Bash 基礎知識系列 #2：在 Bash 中使用變量 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基礎知識系列 #2：在 Bash 中使用變量 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基礎知識系列 #2：在 Bash 中使用變量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基礎知識系列 #2：在 Bash 中使用變量 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230619.1 ⭐️⭐️ Bash Basics Series 2 Using Variables in Bash","title":"Bash 基礎知識系列 #2：在 Bash 中使用變量","tag":"202307","desc":""},"relativePath":"202307/20230619.1 ⭐️⭐️ Bash Basics Series 2 Using Variables in Bash.md","filePath":"[post].md"}'),r={name:"202307/20230619.1 ⭐️⭐️ Bash Basics Series 2 Using Variables in Bash.md"};function g(b,s,c,k,u,m){const e=o("Link");return h(),d("div",null,[s[22]||(s[22]=l(`<h1 id="bash-基礎知識系列-2-在-bash-中使用變量" tabindex="-1">Bash 基礎知識系列 #2：在 Bash 中使用變量 <a class="header-anchor" href="#bash-基礎知識系列-2-在-bash-中使用變量" aria-label="Permalink to “Bash 基礎知識系列 #2：在 Bash 中使用變量”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/12/111750bzruv9jiako6j694.jpg" alt=""></p><blockquote><p>在本章的 Bash 基礎知識系列中，學習在 Bash 腳本中使用變量。</p></blockquote><p>在 Bash 基礎知識系列的第一部分中，我簡要提到了變量。現在是時候在本章中詳細瞭解它們了。</p><p>如果你曾經進行過任何類型的編碼，你一定熟悉術語“變量”。</p><p>如果沒有，請將變量視為保存信息的盒子，並且該信息可以隨着時間的推移而改變。</p><p>讓我們看看如何使用它們。</p><h3 id="在-bash-shell-中使用變量" tabindex="-1">在 Bash shell 中使用變量 <a class="header-anchor" href="#在-bash-shell-中使用變量" aria-label="Permalink to “在 Bash shell 中使用變量”">​</a></h3><p>打開終端並使用一個隨機的數字 4 初始化變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var=4</span></span></code></pre></div><p>現在你有一個名為 <code>var</code> 的變量，它的值為 <code>4</code>。想驗證一下嗎？ <strong>通過在變量名前添加 <code>$</code> 來訪問變量的值</strong>。這稱為參數擴展。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[abhishek@itsfoss]:~$ echo The value of var is $var</span></span>
<span class="line"><span>The value of var is 4</span></span></code></pre></div><blockquote><p>🚧 變量初始化時 <code>=</code> 前後不能有空格。</p></blockquote><p>如果需要，你可以將該值更改為其他值：</p><p><img src="https://itsfoss.com/content/images/2023/06/Using-variables-in-shell.png" alt="Using variables in shell"></p><p>在 Bash shell 中，變量可以是數字、字符或字符串（包括空格在內的字符）。</p><p><img src="https://itsfoss.com/content/images/2023/06/bash-variables-types.png" alt="Different variable types in Bash shell"></p><blockquote><p>💡 與 Linux 中的其他事物一樣，變量名稱也區分大小寫。它們可以由字母、數字和下劃線 “<code>_</code>” 組成。</p></blockquote><h3 id="在-bash-腳本中使用變量" tabindex="-1">在 Bash 腳本中使用變量 <a class="header-anchor" href="#在-bash-腳本中使用變量" aria-label="Permalink to “在 Bash 腳本中使用變量”">​</a></h3><p>你是否注意到我沒有運行 shell 腳本來顯示變量示例？ 你可以直接在 shell 中做很多事情.當你關閉終端時，你創建的那些變量將不再存在。</p><p>但是，你的發行版通常會添加全局變量，以便可以在所有腳本和 shell 中訪問它們。</p><p>讓我們再寫一些腳本.你應該之前創建了腳本目錄，但無論哪種情況，此命令都會處理該目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p bash_scripts &amp;&amp; cd bash_scripts</span></span></code></pre></div><p>基本上，如果 <code>bash_scripts</code> 目錄尚不存在，它將創建它，然後切換到該目錄。</p><p>這裏讓我們使用以下文本創建一個名為 <code>knock.sh</code> 的新腳本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo knock, knock</span></span>
<span class="line"><span>echo &quot;Who&#39;s there?&quot;</span></span>
<span class="line"><span>echo &quot;It&#39;s me, $USER&quot;</span></span></code></pre></div><p>更改文件權限並運行腳本。你在上一章中已經學到了。</p><p>這是它為我生成的內容：</p><p><img src="https://itsfoss.com/content/images/2023/06/using-global-variable-bash-script.png" alt="Using global variable in Bahs script"></p><p><strong>你是否注意到它如何自動將我的名字添加到其中？</strong> 這就是包含用户名的全局變量 <code>$USER</code> 的魔力。</p>`,30)),n("p",null,[s[1]||(s[1]=a("你可能還注意到，我有時將 ",-1)),s[2]||(s[2]=n("code",null,'"',-1)),s[3]||(s[3]=a(" 與 ",-1)),s[4]||(s[4]=n("code",null,"echo",-1)),s[5]||(s[5]=a(" 一起使用，但其他時候則不使用。這是故意的。",-1)),i(e,{href:"https://linuxhandbook.com:443/quotes-in-bash/"},{default:t(()=>[...s[0]||(s[0]=[a("bash 中的引號",-1)])]),_:1}),s[6]||(s[6]=a(" 有特殊含義。它們可用於處理空格和其他特殊字符。讓我展示一個例子。",-1))]),s[23]||(s[23]=l(`<h3 id="處理變量中的空格" tabindex="-1">處理變量中的空格 <a class="header-anchor" href="#處理變量中的空格" aria-label="Permalink to “處理變量中的空格”">​</a></h3><p>假設你必須使用一個名為 <code>greetings</code> 的變量，其值為 <code>hello and welcome</code>。</p><p>如果你嘗試像這樣初始化變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>greetings=Hello and Welcome</span></span></code></pre></div><p>你會得到這樣的錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Command &#39;and&#39; not found, but can be installed with:</span></span>
<span class="line"><span>sudo apt install and</span></span></code></pre></div><p>這就是為什麼你需要使用單引號或雙引號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>greetings=&quot;Hello and Welcome&quot;</span></span></code></pre></div><p>現在你可以根據需要使用該變量。</p><p><img src="https://itsfoss.com/content/images/2023/06/using-spaces-in-bash-variable.png" alt="Using spaces in variable names in bash"></p><h3 id="將命令輸出分配給變量" tabindex="-1">將命令輸出分配給變量 <a class="header-anchor" href="#將命令輸出分配給變量" aria-label="Permalink to “將命令輸出分配給變量”">​</a></h3><p>是的！你可以將命令的輸出存儲在變量中並在腳本中使用它們。這稱為命令替換。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var=$(command)</span></span></code></pre></div><p>這是一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[abhishek@itsfoss]:~$ today=$(date +%D)</span></span>
<span class="line"><span>[abhishek@itsfoss]:~$ echo &quot;Today&#39;s date is $today&quot;</span></span>
<span class="line"><span>Today&#39;s date is 06/19/23</span></span>
<span class="line"><span>[abhishek@itsfoss]:~$</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/command-substitue-bash-variable.png" alt="Command substitution in bash"></p><p>舊語法使用反引號而不是 <code>$()</code> 進行命令替換。雖然它可能仍然有效，但你應該使用新的推薦符號。</p><blockquote><p>💡 變量會更改值，除非你聲明一個“常量”變量，如下所示：<code>readonly pi=3.14</code>。在這種情況下，變量 <code>pi</code> 的值無法更改，因為它被聲明為 <code>readlonly</code>。</p></blockquote><h3 id="🏋️-練習時間" tabindex="-1">🏋️ 練習時間 <a class="header-anchor" href="#🏋️-練習時間" aria-label="Permalink to “🏋️ 練習時間”">​</a></h3><p>是時候練習你所學到的東西了。這裏有一些練習來測試你的學習情況。</p><p><strong>練習 1</strong>：編寫一個 bash 腳本，以以下格式打印你的用户名、當前工作目錄、主目錄和默認 shell。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hello, there</span></span>
<span class="line"><span>My name is XYZ</span></span>
<span class="line"><span>My current location is XYZ</span></span>
<span class="line"><span>My home directory is XYZ</span></span>
<span class="line"><span>My default shell is XYZ</span></span></code></pre></div><p><strong>提示</strong>：使用全局變量 <code>$USER</code>、<code>$PWD</code>、<code>$HOME</code> 和 <code>$SHELL</code>。</p><p><strong>練習 2：</strong> 編寫一個 bash 腳本，聲明一個名為 <code>price</code> 的變量.使用它來獲取以下格式的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Today&#39;s price is $X</span></span>
<span class="line"><span>Tomorrow&#39;s price is $Y</span></span></code></pre></div><p>其中 X 是變量 <code>price</code> 的初始值，並且明天價格翻倍。</p><p><strong>提示</strong>：使用 <code>\\</code> 轉義特殊字符 <code>$</code>。</p><p>練習的答案可以在社區的這個專用帖子中討論。</p><p>在 Bash 基礎知識系列的下一章中，你將瞭解如何通過傳遞參數和接受用户輸入來使 bash 腳本具有交互性。</p><p><em>（題圖：MJ/37c5c26e-3289-4ebd-b8ae-88eb8a3b2eb1）</em></p><hr>`,31)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://itsfoss.com/bash-use-variables/"},{default:t(()=>[...s[7]||(s[7]=[a("https://itsfoss.com/bash-use-variables/",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...s[9]||(s[9]=[a("Abhishek Prakash",-1)])]),_:1}),s[14]||(s[14]=a(" 選題：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[10]||(s[10]=[a("lkxed",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const C=p(r,[["render",g]]);export{v as __pageData,C as default};
